// The world map (public/world.svg, one <path id="ISO2"> per country), fetched once and coloured
// per page. Generated by tools/world-map.mjs from Natural Earth; Morocco includes Western Sahara.
let world: Promise<string> | null = null;

export function loadWorld(): Promise<string> {
  world ??= fetch("/world.svg").then((r) => (r.ok ? r.text() : ""));
  return world;
}

/** Draw the map into `el`, colouring each country. */
export function colourMap(el: HTMLElement, svg: string, paint: (code: string) => { fill: string; title?: string }): void {
  if (!svg) return;
  if (!el.querySelector("svg")) el.innerHTML = svg;
  el.querySelectorAll<SVGPathElement>("path[id]").forEach((p) => {
    const { fill, title } = paint(p.id);
    p.setAttribute("fill", fill);
    const t = p.querySelector("title");
    if (t && title) t.textContent = title;
  });
}

/** Frame the map around one country, with some of its neighbours for context. */
export function zoomTo(el: HTMLElement, code: string, pad = 2.6): void {
  const svg = el.querySelector("svg");
  const p = svg?.querySelector<SVGPathElement>(`path[id="${code}"]`);
  if (!svg || !p) return;
  const b = p.getBBox();
  const size = Math.max(b.width, b.height, 18) * pad;
  const cx = b.x + b.width / 2, cy = b.y + b.height / 2;
  svg.setAttribute("viewBox", `${cx - size / 2} ${cy - size / 2} ${size} ${size}`);
}
